import React, { useState } from 'react';

function ComboScreen({ ticketTotal = 0, onBack, onNext }) {
  const combos = [
    { id: 'popcorn-small', name: 'Bắp nhỏ', price: 30000 },
    { id: 'popcorn-large', name: 'Bắp lớn', price: 50000 },
    { id: 'drink', name: 'Nước', price: 25000 }
  ];

  const [counts, setCounts] = useState({});

  const groupSize = counts['drink'] || 0;
  const freeDrinkCount = groupSize >= 5 ? 1 : 0;
  const studentDiscountText = 'Sinh viên giảm 30% khi xuất trình thẻ';
  const childDiscountText = 'Trẻ em dưới 14 tuổi giảm 50% giá vé gốc';
  const coupleOfferText = 'Ưu đãi cặp đôi: bắp + nước combo giá tốt';

  const changeCount = (id, delta) => {
    const prev = counts[id] || 0;
    const next = Math.max(0, prev + delta);
    setCounts({ ...counts, [id]: next });
  };

  const comboTotal = combos.reduce((sum, c) => sum + (counts[c.id] || 0) * c.price, 0);

  return (
    <div style={{ color: '#e2e8f0', minHeight: '80vh' }}>
      <button
        className="btn mb-4 fw-bold text-white border-0"
        style={{
          background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)',
          boxShadow: '0 18px 28px rgba(124, 58, 237, 0.28)'
        }}
        onClick={onBack}
      >⬅ Quay lại chọn ghế</button>

      <div
        className="card p-4 shadow-sm border-0"
        style={{
          background: 'rgba(15, 23, 42, 0.94)',
          border: '1px solid rgba(79, 70, 229, 0.18)'
        }}
      >
        <h3 className="fw-bold mb-3" style={{ color: '#c4b5fd' }}>Chọn Combo Bắp & Nước</h3>
        <div className="d-flex flex-column flex-sm-row gap-3 mb-4" style={{ color: '#cbd5e1' }}>
          <div style={{ flex: 1, minWidth: 200, padding: 16, borderRadius: 18, background: 'rgba(99, 102, 241, 0.12)', border: '1px solid rgba(99, 102, 241, 0.18)' }}>
            <div className="fw-bold mb-2" style={{ color: '#e0e7ff' }}>🎓 Ưu đãi sinh viên</div>
            <div>{studentDiscountText}</div>
          </div>
          <div style={{ flex: 1, minWidth: 200, padding: 16, borderRadius: 18, background: 'rgba(16, 185, 129, 0.12)', border: '1px solid rgba(16, 185, 129, 0.18)' }}>
            <div className="fw-bold mb-2" style={{ color: '#dcfce7' }}>👶 Ưu đãi trẻ em</div>
            <div>{childDiscountText}</div>
          </div>
          <div style={{ flex: 1, minWidth: 200, padding: 16, borderRadius: 18, background: 'rgba(244, 63, 94, 0.12)', border: '1px solid rgba(244, 63, 94, 0.18)' }}>
            <div className="fw-bold mb-2" style={{ color: '#fed7e2' }}>💑 Ưu đãi cặp đôi</div>
            <div>{coupleOfferText}</div>
          </div>
        </div>

        <div className="row g-3">
          {combos.map(c => (
            <div
              key={c.id}
              className="col-12 d-flex align-items-center justify-content-between p-3"
              style={{
                borderRadius: 16,
                background: 'rgba(15, 23, 42, 0.88)',
                border: '1px solid rgba(148, 163, 184, 0.12)'
              }}
            >
              <div>
                <div className="fw-bold" style={{ color: '#e2e8f0' }}>{c.name}</div>
                <div className="small" style={{ color: '#94a3b8' }}>{c.price.toLocaleString()}đ</div>
                {c.id === 'drink' && (
                  <div className="small mt-1" style={{ color: '#a5b4fc' }}>Đặt 5 nước trở lên tặng 1 nước miễn phí.</div>
                )}
                {c.id === 'popcorn-large' && (
                  <div className="small mt-1" style={{ color: '#a5b4fc' }}>Combo cặp đôi: bắp lớn + nước là lựa chọn lý tưởng.</div>
                )}
              </div>
              <div className="d-flex align-items-center gap-2">
                <button
                  className="btn btn-sm"
                  style={{
                    background: 'rgba(255, 255, 255, 0.06)',
                    color: '#e2e8f0',
                    border: '1px solid rgba(148, 163, 184, 0.22)',
                    width: '36px',
                    height: '36px'
                  }}
                  onClick={() => changeCount(c.id, -1)}
                >-</button>
                <div style={{ minWidth: 28, textAlign: 'center', color: '#e2e8f0' }}>{counts[c.id] || 0}</div>
                <button
                  className="btn btn-sm"
                  style={{
                    background: 'rgba(255, 255, 255, 0.06)',
                    color: '#e2e8f0',
                    border: '1px solid rgba(148, 163, 184, 0.22)',
                    width: '36px',
                    height: '36px'
                  }}
                  onClick={() => changeCount(c.id, 1)}
                >+</button>
              </div>
            </div>
          ))}
        </div>

        {freeDrinkCount > 0 && (
          <div className="mb-3" style={{ padding: '14px 18px', borderRadius: 18, background: 'rgba(16, 185, 129, 0.12)', border: '1px solid rgba(16, 185, 129, 0.18)', color: '#d1fae5' }}>
            🎁 Chúc mừng! Bạn đủ điều kiện nhận <strong>{freeDrinkCount} nước miễn phí</strong> khi đặt 5 nước trở lên.
          </div>
        )}
        <div className="d-flex justify-content-between align-items-center mt-4" style={{ color: '#cbd5e1' }}>
          <div className="fw-bold">Tổng Combo:</div>
          <div className="fs-5 fw-bold" style={{ color: '#c4b5fd' }}>{comboTotal.toLocaleString()}đ</div>
        </div>

        <div className="d-flex gap-2 mt-4 flex-wrap">
          <button
            className="btn fw-bold py-2"
            style={{
              background: 'rgba(255, 255, 255, 0.08)',
              color: '#e2e8f0',
              borderRadius: 10,
              minWidth: '120px'
            }}
            onClick={onBack}
          >Quay lại</button>
          <button
            className="btn fw-bold py-2"
            style={{
              background: 'rgba(255, 255, 255, 0.05)',
              color: '#cbd5e1',
              border: '1px solid rgba(148, 163, 184, 0.18)',
              borderRadius: 10,
              minWidth: '160px'
            }}
            onClick={() => onNext({ comboCounts: {}, comboTotal: 0 })}
          >Bỏ qua mua combo</button>
          <button
            className="btn fw-bold text-white py-2"
            style={{
              background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)',
              borderRadius: 10,
              minWidth: '160px'
            }}
            onClick={() => onNext({ comboCounts: counts, comboTotal })}
          >Tiếp tục thanh toán</button>
        </div>
      </div>
    </div>
  );
}

export default ComboScreen;
